/// <summary>
/// Contract class for Ready for Pricing business events
/// </summary>
[DataContract]
public final class METSOReturnAndClaimsBusinessEventContract  extends BusinessEventsContract
{
    private SalesReturnItemNum rmaNumber;

}

Method.Source:
    /// <summary>
    /// Parm method for Sales Id 
    /// </summary>
    /// <param name = "_rmaNumber">RMA number</param>
    /// <returns>RMA Number</returns>
    [DataMember(identifierStr(SalesReturnItemNum)), BusinessEventsDataMember("@SYS24699")]
    public SalesReturnItemNum parmRMANumber(SalesReturnItemNum _rmaNumber = rmaNumber)
    {
        rmaNumber = _rmaNumber;

        return rmaNumber;
    }

    /// <summary>
    /// Create contract instance using SalesTable
    /// </summary>
    /// <param name = "_salesTable">Salestable</param>
    /// <returns>An instance of <c>METSOReturnAndClaimsBusinessEventContract</c></returns>
    public static METSOReturnAndClaimsBusinessEventContract newFromSalesTable(SalesTable _salesTable)
    {
        var contract = new METSOReturnAndClaimsBusinessEventContract();
        contract.initialize(_salesTable);

        return contract;
    }

/// <summary>
/// Initialize the data contract
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
private void initialize(SalesTable _salesTable)
{
    rmaNumber = _salesTable.ReturnItemNum;
}
